const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];

/** "2026-09" -> "September 2026"; anything else is passed through. */
function monthName(period) {
  const m = /^(\d{4})-(\d{2})$/.exec(period);
  if (!m || Number(m[2]) < 1 || Number(m[2]) > 12) return period;
  return `${MONTHS[Number(m[2]) - 1]} ${m[1]}`;
}

/** Whole cents -> "1,234.56" (negative: "-1,234.56"), exact, no floating point. */
function money(cents) {
  const sign = cents < 0 ? "-" : "";
  const abs = Math.abs(cents);
  const dollars = String(Math.floor(abs / 100)).replace(/\B(?=(\d{3})+$)/g, ",");
  return `${sign}${dollars}.${String(abs % 100).padStart(2, "0")}`;
}

const count = (n) => String(n).replace(/\B(?=(\d{3})+$)/g, ",");

/**
 * The monthly usage statement as plain text.
 * @param {{ customer: string, account: string, period: string, currency: string,
 *           lines: { service: string, quantity: number, unit: string, amount_cents: number }[],
 *           credits: { reason: string, amount_cents: number }[] }} data
 * @returns {string}
 */
export function renderStatement(data) {
  const charges = data.lines.map((l) => ({
    label: l.service,
    qty: count(l.quantity),
    unit: l.unit,
    amount: money(l.amount_cents),
  }));
  const credits = data.credits.map((c) => ({ label: c.reason, amount: money(c.amount_cents) }));

  const chargeCents = data.lines.reduce((s, l) => s + l.amount_cents, 0);
  const creditCents = data.credits.reduce((s, c) => s + c.amount_cents, 0);
  const totalCents = chargeCents + creditCents;

  const subtotal = money(chargeCents);
  const totalText = money(totalCents);
  const amountHeader = `Amount (${data.currency})`;

  const labelW = Math.max(
    "Service".length, "Total charges".length, "Total due".length,
    ...charges.map((c) => c.label.length), ...credits.map((c) => c.label.length),
  );
  const qtyW = Math.max("Quantity".length, ...charges.map((c) => c.qty.length));
  const unitW = Math.max("Unit".length, ...charges.map((c) => c.unit.length));
  const amtW = Math.max(
    amountHeader.length, subtotal.length, totalText.length,
    ...charges.map((c) => c.amount.length), ...credits.map((c) => c.amount.length),
  );

  const gap = "  ";
  const width = labelW + gap.length + qtyW + 1 + unitW + gap.length + amtW;
  const rule = "-".repeat(width);
  const amountAt = (label, amount) =>
    `${label.padEnd(width - amtW)}${amount.padStart(amtW)}`;

  const out = [];
  out.push(`Usage statement for ${data.customer}`);
  out.push(`Account ${data.account}, ${monthName(data.period)}`);
  out.push("");
  out.push(
    `${"Service".padEnd(labelW)}${gap}${"Quantity".padStart(qtyW)} ${"Unit".padEnd(unitW)}${gap}${amountHeader.padStart(amtW)}`,
  );
  out.push(rule);
  for (const c of charges) {
    out.push(
      `${c.label.padEnd(labelW)}${gap}${c.qty.padStart(qtyW)} ${c.unit.padEnd(unitW)}${gap}${c.amount.padStart(amtW)}`,
    );
  }
  out.push(rule);
  out.push(amountAt("Total charges", subtotal));
  out.push("");
  if (credits.length > 0) {
    out.push("Credits");
    for (const c of credits) out.push(amountAt(c.label, c.amount));
    out.push("");
  }
  out.push("=".repeat(width));
  out.push(amountAt(`Total due (${data.currency})`, totalText));
  out.push("=".repeat(width));
  return `${out.map((l) => l.replace(/\s+$/, "")).join("\n")}\n`;
}
